import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-token'];
  if (!token) return res.status(401).json({ error: 'missing token' });
  // In production this would verify JWT signature
  const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
  req.tenantId = payload.tenant_id;
  req.userRole = payload.role;
  next();
}

// Search endpoint with dynamic filtering
app.post('/api/v2/assets/search', extractTenant, async (req, res) => {
  try {
    const { filters, fields, sort_by, limit } = req.body;

    // Build allowed fields list
    const allowedFields = ['id', 'name', 'category', 'status', 'created_at', 'value'];
    const selectFields = (fields || ['id', 'name']).filter(f => allowedFields.includes(f));

    let query = `SELECT ${selectFields.join(', ')} FROM assets WHERE tenant_id = $1`;
    const params = [req.tenantId];
    let paramIdx = 2;

    // Apply filters
    if (filters) {
      for (const [key, condition] of Object.entries(filters)) {
        if (!allowedFields.includes(key)) continue;

        if (condition.op === 'eq') {
          query += ` AND ${key} = $${paramIdx}`;
          params.push(condition.value);
          paramIdx++;
        } else if (condition.op === 'like') {
          query += ` AND ${key} LIKE $${paramIdx}`;
          params.push(condition.value);
          paramIdx++;
        } else if (condition.op === 'in') {
          const placeholders = condition.value.map((_, i) => `$${paramIdx + i}`).join(',');
          query += ` AND ${key} IN (${placeholders})`;
          params.push(...condition.value);
          paramIdx += condition.value.length;
        } else if (condition.op === 'between') {
          query += ` AND ${key} BETWEEN $${paramIdx} AND $${paramIdx + 1}`;
          params.push(condition.value[0], condition.value[1]);
          paramIdx += 2;
        }
      }
    }

    // Sort - VULNERABLE: sort_by is not validated against allowedFields
    if (sort_by) {
      query += ` ORDER BY ${sort_by}`;
    }

    // Limit
    const safeLimit = Math.min(parseInt(limit) || 50, 500);
    query += ` LIMIT ${safeLimit}`;

    const result = await pool.query(query, params);

    res.json({
      data: result.rows,
      meta: { total: result.rows.length, query_id: crypto.randomUUID() }
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'internal error', detail: err.message });
  }
});

// Admin endpoint for bulk operations
app.post('/api/v2/assets/bulk-update', extractTenant, async (req, res) => {
  if (req.userRole !== 'admin') return res.status(403).json({ error: 'forbidden' });
  const { ids, updates } = req.body;
  const setClauses = Object.entries(updates)
    .filter(([k]) => ['status', 'category'].includes(k))
    .map(([k, v], i) => `${k} = $${i + 2}`)
    .join(', ');
  const values = Object.entries(updates).filter(([k]) => ['status', 'category'].includes(k)).map(([, v]) => v);

  if (!setClauses) return res.status(400).json({ error: 'no valid fields' });

  const result = await pool.query(
    `UPDATE assets SET ${setClauses} WHERE tenant_id = $1 AND id = ANY($${values.length + 2})`,
    [req.tenantId, ...values, ids]
  );
  res.json({ updated: result.rowCount });
});

app.listen(3000, () => console.log('Asset service running on :3000'));
